const enhancements = {

'17-1': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Project Planning Framework Drill', content: 'Learn the key elements of AI-assisted project planning.\n\n**Step 1 — Ask Claude:** "What are the elements of a good project plan that AI can help with, and which require human judgement? For each element, what AI assistance is most valuable?"\n\n**Step 2 — Apply the framework** to a real project you\'re starting or currently running.\n\n**Step 3 — Ask Claude to create a project plan outline:**\n```\nCreate a project plan outline for:\nProject: [describe it]\nGoal: [specific outcome]\nTimeline: [available time]\nTeam: [who\'s involved]\nConstraints: [budget, technical, resource]\n\nInclude: milestones, dependencies, risk areas, and success criteria.\n```\n\n**Step 4 — Review the outline.** What did Claude miss that you know about this project?\n\n**Step 5 — Add the missing context** and ask Claude to refine the plan.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Real Project Plan', content: 'Create a complete project plan with AI assistance.\n\n**Step 1 — Choose a real project** starting in the next 30 days.\n\n**Step 2 — Ask Claude to generate a detailed plan:**\n```\nCreate a detailed project plan:\nProject: [name and description]\nDeadline: [date]\nKey deliverables: [list them]\nTeam members and roles: [list]\nKnown risks: [list]\n\nProvide:\n1. Work breakdown structure (WBS)\n2. Timeline with milestones\n3. Dependencies (what must be done before what)\n4. Risk register with mitigation strategies\n5. Communication plan (who needs to know what, when)\n```\n\n**Step 3 — Review each section** for accuracy — Claude can\'t know your team\'s actual capacity or organisational dynamics.\n\n**Step 4 — Mandatory review:** Ask Claude: *"What critical risks have I not identified? What project failure modes are common for this type of project?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Risk Assessment Deep Dive', content: 'Use AI to identify and mitigate project risks.\n\n**Step 1 — Take your project plan** from Workshop B.\n\n**Step 2 — Ask Claude to conduct a risk analysis:**\n```\nConduct a thorough risk analysis for this project [describe it].\n\nFor each risk identify:\n- Probability: High/Medium/Low\n- Impact if it occurs: High/Medium/Low\n- Risk score: Probability × Impact\n- Mitigation strategy\n- Contingency plan (if mitigation fails)\n\nInclude both technical risks and people/process risks.\n```\n\n**Step 3 — Sort risks by score** (High/High = most critical).\n\n**Step 4 — For the top 3 risks**, ask Claude to design detailed mitigation plans.\n\n**Step 5 — Add early warning signals** for each risk: "How will I know this risk is materialising before it becomes a crisis?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Stakeholder Communication Plan', content: 'Create a communication plan for your project stakeholders.\n\n**Step 1 — List all stakeholders** for your project: everyone who is affected by or interested in the project outcome.\n\n**Step 2 — Ask Claude to create a stakeholder communication plan:**\n```\nCreate a stakeholder communication plan for [project].\n\nStakeholders:\n- [Name/Role]: [what they care about, how much detail they want]\n\nFor each stakeholder, specify:\n- Communication frequency\n- Format (email, meeting, dashboard, report)\n- Content (what they need to know)\n- Who sends it\n```\n\n**Step 3 — Review the plan.** Does it match your stakeholders\' actual preferences?\n\n**Step 4 — Create the first communication** from the plan — a project kickoff message to all stakeholders.' },

    { type: 'quiz', question: 'Claude creates a project timeline with 5 parallel workstreams finishing exactly on the same date. What critical planning element is likely missing?', options: ['The timeline is well-designed — parallel work is efficient', 'Buffer time and integration risk: when parallel workstreams must merge, integration issues almost always emerge. Add integration time and buffer between the merge date and the final deadline', 'A Gantt chart visualization', 'Resource allocation across the workstreams'], correct: 1, explanation: 'Parallel workstreams that merge simultaneously are a classic scheduling risk. Integration problems (dependencies don\'t match, interfaces between workstreams have bugs, outputs are in incompatible formats) are the rule, not the exception. Best practice: plan for parallel streams to finish 20-30% before the integration deadline, add an explicit integration and testing phase, and add buffer between the integration merge and the final deadline.' },

    { type: 'quiz', question: 'A project risk is "key team member might leave during the project." Claude rates it Low/Low. Do you agree?', options: ['Yes — key person risk is usually overstated', 'Not necessarily — rate risks based on YOUR context. If the person is truly irreplaceable and no knowledge transfer exists, this could be Medium/High. Re-rate risks based on your actual situation, not generic assessments', 'Yes — companies should plan for 0% turnover', 'Only rate it higher if you have specific reason to think they\'ll leave'], correct: 1, explanation: 'AI rates risks based on typical cases, not your specific situation. Generic risk assessments need calibration to your context. Key person dependency is "Low/Low" if there\'s good documentation and cross-training. It\'s "High/High" if one person holds critical undocumented knowledge, has been talking to recruiters, or is the only person who can make a critical system work. Review every AI risk rating against your actual situation.' }
  ]
},

'17-2': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Problem Decomposition Drill', content: 'Practice breaking complex problems into solvable pieces.\n\n**Step 1 — Choose a genuinely complex problem** you\'re facing: a technical challenge, a strategic decision, an operational problem.\n\n**Step 2 — Ask Claude to decompose it:**\n```\nHelp me break down this complex problem:\n[describe the problem]\n\nDecompose it into:\n1. Sub-problems (what are the distinct components?)\n2. Dependencies (which sub-problems depend on solving others first?)\n3. Knowns vs unknowns (what do we know? what do we need to discover?)\n4. Quick wins (what can be solved immediately with high confidence?)\n5. Long-pole items (what will take the most time/resources?)\n```\n\n**Step 3 — Review the decomposition.** Does it match your understanding?\n\n**Step 4 — Identify the first sub-problem to tackle** and start working on it.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Root Cause Analysis', content: 'Use AI to conduct a rigorous root cause analysis.\n\n**Step 1 — Choose a problem or failure** that occurred recently.\n\n**Step 2 — Apply the 5 Whys with AI:**\n```\nConduct a root cause analysis using the 5 Whys method.\n\nProblem: [describe what happened]\n\nFor each "why," don\'t accept the first answer — dig one level deeper:\nWhy 1: Why did [problem] happen?\nWhy 2: Why did [answer to why 1] happen?\n...continue 5 levels deep.\n\nAt the end, identify: what is the true root cause? Is it a system problem or a people problem?\n```\n\n**Step 3 — Validate the root cause.** Does it explain all instances of the problem?\n\n**Step 4 — Design a fix for the root cause** (not a band-aid for the symptom).\n\n**Step 5 — Mandatory review:** Ask Claude: *"Is the root cause you identified actually addressable? Or does it lead to another problem that can\'t be solved?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Decision Tree Construction', content: 'Build a decision tree for a complex multi-step decision.\n\n**Step 1 — Identify a decision** with multiple branches and conditional paths.\n\n**Step 2 — Ask Claude to build a decision tree:**\n```\nCreate a decision tree for this situation:\n[describe the decision context]\n\nFor each decision point:\n- What question determines the branch?\n- What are the possible answers?\n- What action does each answer lead to?\n- What are the terminal states (final outcomes)?\n\nFormat as a text-based decision tree I can follow.\n```\n\n**Step 3 — Test the decision tree** on 3 different scenarios. Does it lead to the right decisions?\n\n**Step 4 — Identify any missing branches** — scenarios the tree doesn\'t handle.\n\n**Step 5 — Share with colleagues** as a shared decision framework.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Complexity Reduction', content: 'Use AI to identify which complexity in a problem can be eliminated.\n\n**Step 1 — Describe a complex problem** you\'re working on.\n\n**Step 2 — Ask Claude:**\n```\nI\'m dealing with this complex problem: [describe it]\n\nHelp me reduce unnecessary complexity:\n1. What aspects of this problem are complex because they need to be vs complex because of how we\'ve approached them?\n2. What constraints are real vs assumed?\n3. What would a simple, direct solution look like? (Even if it seems too simple)\n4. What is the minimum viable solution that addresses the core problem?\n5. What am I overcomplicating?\n```\n\n**Step 3 — Evaluate the "simple solution."** Is it actually too simple, or is it workable?\n\n**Step 4 — Try the simplest approach first** before adding complexity back in.' },

    { type: 'quiz', question: 'You\'re solving a complex technical problem and Claude gives you a very detailed decomposition with 15 sub-problems. What should you do?', options: ['Solve all 15 sub-problems simultaneously for maximum efficiency', 'Prioritise: identify the 2-3 sub-problems that are blocking everything else or that have the highest impact if unsolved — solve those first', 'Delegate each sub-problem to a different team member', 'Ask Claude to reduce it to 5 sub-problems maximum'], correct: 1, explanation: 'Not all sub-problems are equal. The critical path principle: some sub-problems block everything else (must be solved first), some have high impact, and some are edge cases that matter only if the core solution works. Identify your blocking dependencies first, then your highest-impact items. Solving 15 sub-problems in parallel is usually impossible and often inefficient — dependencies mean you\'ll be blocked waiting for prerequisite sub-problems anyway.' },

    { type: 'quiz', question: 'The 5 Whys root cause analysis leads to "the culture doesn\'t value quality." How useful is this root cause, and what should you do?', options: ['Very useful — culture is the most important factor', 'Not very actionable: "culture" is too large to address directly. Ask: what specific behaviours or incentives create this culture? What is the one behaviour change or process change that would most improve quality?', 'This means the problem is unsolvable', 'Escalate immediately to senior leadership'], correct: 1, explanation: '"Culture" as a root cause is almost always an intermediate cause, not the true root cause. Culture is a result of specific behaviours, incentives, and systems. Push one level deeper: "Why doesn\'t the culture value quality? Is it because quality isn\'t measured? Because speed is rewarded and quality isn\'t? Because there\'s no feedback loop when quality fails?" Each of these has a more specific, actionable fix than "change the culture."' }
  ]
},

'17-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Research-Informed Planning', content: 'Combine research and planning in one integrated workflow.\n\n**Step 1 — Choose a planning task** that requires research first: a technology choice, a market entry decision, a process change.\n\n**Step 2 — Run rapid research** (15 minutes max) using Perplexity and Claude.\n\n**Step 3 — Feed research directly into planning:**\n"Based on this research [paste results], create a plan for [planning task]. The plan should reflect the current state of [technology/market/field] and avoid approaches that the research suggests are outdated or problematic."\n\n**Step 4 — Identify where the plan would be different** without the research. What assumptions would you have made?\n\n**Step 5 — Ask Claude:** "What remaining research gaps would most improve this plan if filled?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Evidence-Based Decision Making', content: 'Make a significant decision using evidence gathered through AI research.\n\n**Step 1 — Identify a real decision** you need to make that deserves research.\n\n**Step 2 — Design the research:** what evidence would help you decide?\n\n**Step 3 — Gather the evidence** using AI research tools.\n\n**Step 4 — Ask Claude to structure the decision:**\n```\nHelp me make this decision: [describe it]\n\nBased on this evidence: [paste research]\n\nStructure as:\n1. Decision criteria: what factors matter most?\n2. Options: what are the realistic choices?\n3. Evidence for each option: what does the research support?\n4. Recommendation: which option does the evidence most support?\n5. Key uncertainty: what would change this recommendation?\n```\n\n**Step 5 — Make the decision.** Document your reasoning for future reference.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Research Quality for Planning', content: 'Ensure your planning research is sufficient quality to act on.\n\n**Step 1 — For a plan you\'ve created**, list every assumption the plan makes.\n\n**Step 2 — For each assumption**, ask: Is this based on research? On experience? On assumption?\n\n**Step 3 — Identify the highest-risk assumptions** (ones where if you\'re wrong, the plan fails).\n\n**Step 4 — Ask Claude to challenge your highest-risk assumption:**\n"I\'m planning based on this assumption: [describe it]. What evidence would contradict this assumption? What scenarios would make this assumption wrong?"\n\n**Step 5 — Either find evidence to support the assumption** or adjust the plan to be more robust if the assumption is wrong.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Plan Stress-Testing', content: 'Systematically stress-test a plan against realistic failure scenarios.\n\n**Step 1 — Take a completed project or decision plan.**\n\n**Step 2 — Ask Claude to generate failure scenarios:**\n```\nStress-test this plan [describe it] against realistic failure scenarios.\n\nFor each scenario:\n1. Describe what happens\n2. At what point in the plan does it cause problems?\n3. What is the impact?\n4. How would I detect it early?\n5. What is the contingency response?\n\nGenerate: 3 likely scenarios, 2 unlikely but plausible scenarios, 1 worst-case scenario.\n```\n\n**Step 3 — For each failure scenario**, decide: Does the plan need to change? Or is the contingency response adequate?\n\n**Step 4 — Update the plan** based on the stress test findings.' },

    { type: 'quiz', question: 'You plan a product launch based on AI-researched market data showing strong demand. Before committing budget, what additional validation is most important?', options: ['Get more AI research to confirm the findings', 'Talk to potential customers directly: AI research aggregates existing information, but customer interviews reveal what people actually want vs what they say in surveys', 'Hire a market research firm', 'Check competitor products for similar features'], correct: 1, explanation: 'AI research tells you what has been written about a market — articles, surveys, reports. Customer interviews tell you what specific people in your target market actually think and would pay for. These often diverge significantly. The highest-value validation before committing budget: 5-10 interviews with people who match your target customer profile. Ask about their actual behaviour and spending, not hypothetical interest. "Would you use a product that does X?" produces unreliable answers; "How do you currently solve this problem and what do you pay for it?" produces actionable data.' },

    { type: 'quiz', question: 'Your research says one approach is best, but your experience suggests another approach works better. Which should you trust?', options: ['Always trust research over experience', 'Always trust experience over research', 'Investigate the discrepancy: determine whether the research applies to your specific context, whether your experience is representative, and what would help resolve the conflict', 'Use both approaches in parallel and see which works'], correct: 2, explanation: 'Discrepancy between research and experience is valuable signal, not a problem to dismiss. Investigate: (1) Does the research apply to your specific context (company size, industry, geography)? (2) Is your experience based on enough cases to be generalizable, or is it a sample of 1-2? (3) Are you measuring the same thing? (4) Has something changed since the research was conducted? Understanding why they conflict often produces better insights than either source alone.' }
  ]
},

'17-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Decision Documentation Drill', content: 'Build the habit of documenting decisions as you make them.\n\n**Step 1 — Ask Claude:** "What is an Architecture Decision Record (ADR)? How do teams use them? What are the key elements of a good decision record?"\n\n**Step 2 — Create a decision record template** for your context:\n```markdown\n# Decision: [Title]\n**Date:** [YYYY-MM-DD]\n**Status:** Proposed / Accepted / Superseded\n**Context:** [Why does this decision need to be made?]\n**Options considered:** [What alternatives were evaluated?]\n**Decision:** [What was decided and why]\n**Consequences:** [What will be easier/harder as a result?]\n**Revisit when:** [Under what conditions should we revisit this?]\n```\n\n**Step 3 — Document one recent decision** using this template.\n\n**Step 4 — Ask Claude to review the decision record:** "Does this decision record clearly capture the reasoning? What context would a future reader need that isn\'t here?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Decision Journal', content: 'Create a decision journal system for ongoing use.\n\n**Step 1 — Ask Claude Code** to set up a decision journal:\n```\nCreate a simple decision journal system:\n1. A folder ~/decisions/ with one markdown file per major decision\n2. A DECISIONS.md index file with: date, title, status, one-line summary\n3. A template file for new decisions\n4. A monthly review prompt: "Review all decisions from last month — which turned out well? Which poorly? What can you learn?"\n\nSet up the folder structure and initial files.\n```\n\n**Step 2 — Add your 3 most recent significant decisions** to the journal.\n\n**Step 3 — Schedule a monthly review** (calendar reminder) to revisit decisions and assess outcomes.\n\n**Step 4 — After 3 months**, do your first review. What patterns do you see in your decision-making?' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Real-Time Documentation During Work', content: 'Practice capturing context and decisions as you work, not after.\n\n**Step 1 — Set up a quick capture system** — a simple text file, a note in your project, or a CLAUDE.md section:\n```\n## Today\'s Work Log\n\n### Decision: [what you decided]\nContext: [why this decision came up]\nOptions: [what you considered]\nChosen: [what you picked and why]\n\n### Discovery: [something you learned]\nImpact: [how this changes things]\n```\n\n**Step 2 — During your next 2-hour work session**, capture notes in real time:\n- Every decision (even small ones)\n- Every surprising discovery\n- Every blocked path and why\n\n**Step 3 — At the end of the session**, ask Claude to synthesise your log:\n"Summarise this work log into: decisions made, key learnings, and open questions for next session."\n\n**Step 4 — Evaluate:** Did the real-time log capture anything important you would have forgotten?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Team Decision Capture', content: 'Extend decision documentation to your team.\n\n**Step 1 — Identify 3 recent team decisions** that weren\'t documented.\n\n**Step 2 — Try to reconstruct them:** What was the context? What options were considered? Why was this choice made?\n\n**Step 3 — Notice what you can\'t reconstruct** after even a few weeks. This is the cost of not documenting.\n\n**Step 4 — Ask Claude to design a lightweight team decision capture process:**\n"Design a team decision documentation process that: takes under 5 minutes per decision, is stored where the team can find it, and would actually be used consistently. Avoid heavy processes that will be abandoned."\n\n**Step 5 — Propose the process to your team** and pilot it for one month.' },

    { type: 'quiz', question: 'Six months after making a technical decision, a new team member asks "why do we do it this way?" You can\'t remember the reasoning. What does this cost?', options: ['Nothing — they should just trust the existing approach', 'Significant time lost: they may revisit the decision unnecessarily, implement a different approach that conflicts with the existing one, or lose confidence in the team\'s technical choices', 'A quick meeting to discuss it — low cost', 'Only a problem if the decision was wrong'], correct: 1, explanation: 'Undocumented decisions get re-litigated constantly. Team members encounter the decision\'s consequences without understanding its context, leading to: time spent reconstructing the reasoning, risk of reversing a good decision without understanding why it was made, and erosion of confidence in the codebase/process. ADRs and decision journals pay for themselves within the first revisit they prevent — one avoided re-decision meeting pays back years of documentation time.' },

    { type: 'quiz', question: 'A decision record says "we chose PostgreSQL over MongoDB." What critical information is missing that would make this record genuinely useful?', options: ['The date the decision was made', 'The context and reasoning: what were the specific requirements that made PostgreSQL a better fit? What limitations of MongoDB were relevant? Under what conditions should we revisit this choice?', 'Who made the decision', 'A link to the PostgreSQL documentation'], correct: 1, explanation: 'A decision record without reasoning is just a record of what happened, not why. The most valuable part: the context that made this the right choice, the options considered and why they were rejected, and the conditions under which this choice should be reconsidered. Future readers need to know: "Does this reasoning still apply to my situation?" Without the reasoning, they can\'t make that assessment and will either blindly follow the old decision or wastefully re-examine it from scratch.' }
  ]
},

'17-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Quality Review Framework', content: 'Build a quality review framework for your work outputs.\n\n**Step 1 — Ask Claude:** "What are the key dimensions of quality for [your primary output type — code, documents, analysis, designs]? For each dimension, what does excellent vs mediocre look like?"\n\n**Step 2 — Create a quality rubric** specific to your work:\n| Dimension | 1 (Poor) | 3 (Acceptable) | 5 (Excellent) |\n|---|---|---|---|\n| [Dimension 1] | | | |\n| [Dimension 2] | | | |\n\n**Step 3 — Apply the rubric** to a recent work output. Where are you strong? Where is there room to improve?\n\n**Step 4 — Identify the one quality dimension** where AI assistance would add the most value.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI-Assisted Quality Review', content: 'Use AI to conduct quality reviews systematically.\n\n**Step 1 — Take a work output** you\'re about to finalise.\n\n**Step 2 — Ask Claude to review it using your quality rubric:**\n```\nReview this [output type] using this quality rubric:\n[paste the rubric]\n\nFor each dimension:\n1. Score: 1-5\n2. What specifically earned that score\n3. What would be needed to score one point higher\n\nBe specific — use examples from the document.\n```\n\n**Step 3 — Review Claude\'s assessment.** Do you agree with each score?\n\n**Step 4 — Address the 2 lowest-scoring dimensions** before finalising.\n\n**Step 5 — Mandatory self-review:** After the AI review, do your own review. What did the AI miss?**' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Stakeholder Communication for Quality', content: 'Use AI to craft quality-focused stakeholder communications.\n\n**Step 1 — Identify a completed project** or work output ready for stakeholder communication.\n\n**Step 2 — Ask Claude to draft a stakeholder update:**\n```\nWrite a stakeholder update for [project/output]:\n\nAudience: [who they are and what they care about]\nKey messages:\n- What was accomplished\n- Quality indicators (metrics, tests passed, review outcomes)\n- Any known limitations or open items\n- Next steps\n\nTone: [professional/direct/detailed]\nLength: [maximum]\n```\n\n**Step 3 — Review for accuracy and appropriate level of detail** for the audience.\n\n**Step 4 — Add any context** Claude couldn\'t know about the stakeholder relationship or specific concerns.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Retrospective Analysis', content: 'Conduct a rigorous retrospective using AI assistance.\n\n**Step 1 — Choose a completed project** or sprint.\n\n**Step 2 — Ask Claude to facilitate a retrospective:**\n```\nFacilitate a retrospective for this project/sprint:\n[describe what happened — timeline, goals, outcomes, team]\n\nCover these retrospective dimensions:\n1. What went well? (be specific, not generic)\n2. What didn\'t go well? (root causes, not just symptoms)\n3. What surprised us? (things we didn\'t expect)\n4. What should we do differently next time? (specific, actionable)\n5. What should we definitely do again? (specific practices to repeat)\n\nFor each item: identify whether it\'s a process issue, communication issue, technical issue, or people issue.\n```\n\n**Step 3 — Select 2-3 actionable improvements** to implement next sprint/project.\n\n**Step 4 — Document the retro** and schedule a check-in to see if the improvements were made.' },

    { type: 'quiz', question: 'You use AI to review your work and it gives everything a score of 4/5 or 5/5. Should you trust this assessment?', options: ['Yes — if the AI is satisfied, the work is good', 'Be skeptical: AI review can be sycophantic, especially if you\'ve framed the review request in a way that implies the work is good. Ask specifically for problems and weaknesses', 'AI is always accurate in quality assessments', 'Adjust down by 1 point as a standard correction'], correct: 1, explanation: 'AI quality reviews can be overly positive, especially when the work is framed positively or when the review criteria aren\'t specific enough. Countermeasures: (1) explicitly ask for problems rather than balanced feedback: "Find the 3 weakest parts of this document"; (2) use specific, measurable criteria rather than vague dimensions; (3) ask adversarially: "Imagine you\'re a skeptical editor/reviewer — what would you reject this for?"; (4) compare to an explicitly high standard: "Compare this to an excellent example of this document type."' },

    { type: 'quiz', question: 'Your retrospective identifies "better communication" as a needed improvement. Why is this not a useful retrospective output?', options: ['It is useful — communication is always important', '"Better communication" is too vague to act on. Useful retrospective outputs are specific and behavioural: "Send project status updates every Friday by 3pm" or "Raise blockers in daily standup instead of waiting until they\'re critical"', 'It should say "more communication" instead', 'Communication improvements should be handled by HR, not in retrospectives'], correct: 1, explanation: '"Better communication" fails the specificity test — it could mean anything. A good retrospective action is specific enough that you can check whether it happened: "Every PR will have a description explaining the why, not just the what" or "Before escalating to a client, discuss with the team first." Vague improvements get agreed to and then forgotten because there\'s no clear behaviour change to implement. Ask for every retrospective output: "What would \'doing this better\' look like in a specific situation?"' }
  ]
},

'17-6': {
  addMinutes: 25,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Sprint Planning', content: 'Plan a real work sprint using AI tools.\n\n**Step 1 — Define your sprint:**\n- Duration: [1-2 weeks recommended for first sprint]\n- Goal: [one clear outcome]\n- Available time: [total hours available]\n\n**Step 2 — Ask Claude to help you plan the sprint:**\n```\nHelp me plan a [X-day] work sprint.\n\nSprint goal: [describe it]\nAvailable hours: [total]\nContext: [current state, constraints]\n\nCreate:\n1. Task breakdown with time estimates\n2. Priority order (considering dependencies)\n3. Buffer allocation (20% of time for unexpected issues)\n4. Definition of Done for the sprint goal\n5. Daily check-in questions to assess progress\n```\n\n**Step 3 — Review and adjust the plan** based on your actual knowledge of the work.\n\n**Step 4 — Start the sprint.** Use the daily check-in questions.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Mid-Sprint AI Check-in', content: 'Use AI to course-correct during an active work sprint.\n\n**Step 1 — Halfway through your sprint**, conduct an AI-assisted check-in:\n```\nI\'m halfway through a sprint. Help me assess progress.\n\nSprint goal: [original goal]\nPlanned tasks: [list them with original estimates]\nCompleted so far: [what\'s done]\nActual time spent: [hours]\nRemaining time: [hours]\n\nAnalyse:\n1. Am I on track to hit the sprint goal?\n2. Which tasks are over/under estimate?\n3. Should any tasks be deprioritised to protect the sprint goal?\n4. What\'s at risk in the second half?\n```\n\n**Step 2 — Make the recommended adjustments** — don\'t let sunk cost keep you on track for a failing sprint.\n\n**Step 3 — Ask Claude:** "What is the minimum viable version of this sprint goal I can hit if I have only 60% of the remaining time?"' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Sprint Delivery and Documentation', content: 'Complete your sprint and document the outputs.\n\n**Step 1 — At sprint end**, compile your outputs.\n\n**Step 2 — Ask Claude to generate sprint documentation:**\n```\nDocument this completed work sprint:\n\nGoal: [original goal]\nCompleted: [what was actually done]\nNot completed: [what was left out and why]\nKey decisions made: [important choices during the sprint]\nLessons learned: [what would you do differently]\n\nGenerate:\n1. Sprint summary (one page max)\n2. Decision log (decisions made and reasoning)\n3. Lessons learned (2-3 actionable insights)\n4. Next sprint recommendations\n```\n\n**Step 3 — Review the documentation.** Is it accurate?\n\n**Step 4 — Share the sprint summary** with relevant stakeholders.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Continuous Improvement System', content: 'Build a system for continuously improving your AI-augmented work.\n\n**Step 1 — Create a "Work Improvement Log"** — a simple file tracking:\n- What AI workflows saved the most time\n- What AI tools failed or produced poor results\n- New AI techniques tried and their outcomes\n- Prompts that worked exceptionally well\n\n**Step 2 — After each sprint**, spend 10 minutes updating the log.\n\n**Step 3 — Monthly review:** Ask Claude to analyse your improvement log:\n"Based on this improvement log [paste it], what patterns do you see? What should I invest in learning next? What techniques am I not using that would be valuable?"\n\n**Step 4 — Set one concrete improvement goal** for next month based on the analysis.' },

    { type: 'quiz', question: 'Your sprint plan assumed 6 hours for a task that actually took 12 hours. What should you do for future planning?', options: ['Plan more conservatively — double all estimates', 'Investigate why: was the task complexity underestimated, were there interruptions, was research needed? Understanding the cause guides the right correction — don\'t just inflate estimates without understanding why', 'Keep the same estimates — one data point doesn\'t change the model', 'Subtract the overrun from other sprint tasks\' estimates'], correct: 1, explanation: 'Estimation errors need diagnosis before correction. A 12-hour task estimated at 6 hours could be caused by: poor requirements clarity (the task was bigger than understood), unexpected technical complexity, interruptions (the 6 hours of actual work were stretched over 12 hours of calendar time), or systematic optimism bias. Each root cause has a different fix. Without diagnosis, you might just inflate estimates by 2×, which creates false safety and a self-fulfilling prophecy where work expands to fill inflated time budgets.' },

    { type: 'quiz', question: 'At the end of your work sprint, you completed 70% of the planned tasks. Was the sprint successful?', options: ['No — you should complete 100% of planned tasks', 'Depends on whether the sprint goal was achieved. If the 70% you completed included all the highest-priority tasks and the sprint goal is met, this is success. If the 30% you skipped included critical items, it\'s not', 'Yes — 70% completion is a standard industry benchmark', 'No — you need to work overtime to complete the remaining 30%'], correct: 1, explanation: 'Sprint success is measured against the sprint goal, not task completion rate. If you completed the most important 70% including all goal-critical tasks, this may be a successful sprint that also revealed your planning had lower-priority tasks. If the 30% you skipped were goal-critical, the sprint failed regardless of how many total tasks were done. This is why defining a clear sprint goal (single outcome) matters more than planning many tasks.' }
  ]
},

'18-1': {
  addMinutes: 30,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Advanced Prompting Technique Drill', content: 'Test CoT, ToT, and ReAct on the same problem.\n\n**Step 1 — Choose a complex reasoning problem:** a logic puzzle, a complex analysis, a multi-step calculation.\n\n**Step 2 — Test Chain of Thought (CoT):**\n"Think step by step: [your problem]"\n\n**Step 3 — Test Tree of Thought (ToT):**\n"Explore multiple solution paths for [problem]. For each path: describe the approach, take 3 steps, then evaluate whether it\'s promising. After exploring 3 paths, synthesise the best solution."\n\n**Step 4 — Test ReAct (Reasoning + Acting):**\n"For [problem], use the ReAct pattern: Thought → Action → Observation, repeating until you reach a conclusion. Be explicit about each thought and what information you\'re seeking."\n\n**Step 5 — Compare results.** Which technique produced the best outcome for this problem type?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Technique-Matched Prompt Library', content: 'Create a prompt library organised by technique, matching techniques to problem types.\n\n**Step 1 — For each advanced technique**, create a reusable template:\n\n**CoT template:**\n"[Problem]. Let\'s think through this step by step. First... Then... Finally..."\n\n**ToT template:**\n"Explore 3 different approaches to [problem]. For each: take 2 steps of reasoning, then rate its promise (1-5). After exploring all 3, select the best and continue to completion."\n\n**ReAct template:**\n"Solve [problem] using the ReAct pattern. Format each cycle as: Thought: [reasoning], Action: [what to do], Observation: [result]. Continue until you reach a conclusion."\n\n**Step 2 — Test each template** on a problem type it\'s suited for.\n\n**Step 3 — Add to your prompt library** with notes on when to use each.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Technique Selection Framework', content: 'Build a framework for choosing the right advanced prompting technique.\n\n**Step 1 — Ask Claude:** "For these problem types, which advanced prompting technique works best and why? (1) Multi-step math, (2) Open-ended creative generation, (3) Complex decision-making with trade-offs, (4) Debugging code, (5) Research synthesis."\n\n**Step 2 — Build a decision guide:**\n| Problem type | Best technique | Why |\n|---|---|---|\n| Multi-step reasoning | CoT | |\n| Explore alternatives | ToT | |\n| Research and verify | ReAct | |\n\n**Step 3 — Apply the guide** to 3 prompts you commonly write. Which technique should you be using that you haven\'t been?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Implement a ReAct Reasoning Loop', content: 'Build a code implementation of the ReAct pattern.\n\n**Step 1 — Ask Claude Code** to implement a ReAct loop:\n```\nImplement a Python function that uses the ReAct pattern with the Anthropic API:\n1. Takes a problem/question as input\n2. Runs a loop: get a Thought+Action from Claude, execute the action (use web search or calculation), feed back the Observation\n3. Continue until Claude says "I have reached a conclusion"\n4. Return the final answer and the full reasoning chain\n\nFor available actions: web_search(query), calculate(expression), retrieve_document(url)\n(You can mock the action implementations for now)\n```\n\n**Step 2 — Test the ReAct loop** on a multi-step research question.\n\n**Step 3 — Mandatory review:** Ask Claude: *"Review this ReAct implementation. What failure modes exist? How do I prevent infinite loops?"*' },

    { type: 'quiz', question: 'You use Chain of Thought prompting and Claude shows its reasoning but reaches a wrong conclusion. What is the advantage of CoT even when the answer is wrong?', options: ['There is no advantage — a wrong answer is a wrong answer', 'The reasoning chain shows WHERE the error occurred — you can identify the specific step that went wrong and correct it, rather than just knowing the output is wrong', 'CoT answers are always more accurate than direct answers', 'The chain of thought can be used to train a better model'], correct: 1, explanation: 'CoT makes errors inspectable and correctable. Without CoT: "The answer is 47" — wrong, but you don\'t know why. With CoT: "Step 1: [correct], Step 2: [correct], Step 3: [wrong assumption], therefore: 47" — you can see exactly where the reasoning went wrong and correct at that specific step. This is the fundamental advantage of transparent reasoning over black-box outputs, even when the final answer is incorrect.' },

    { type: 'quiz', question: 'Tree of Thought explores multiple reasoning paths before selecting the best one. When does this technique NOT add value?', options: ['ToT never adds value over CoT', 'For problems with one clear correct approach where exploring alternatives wastes time — simple factual questions, standard calculations, or tasks where the path is obvious', 'For creative tasks only', 'For problems requiring more than 5 reasoning steps'], correct: 1, explanation: 'ToT adds value when multiple valid approaches exist and exploring them might reveal a better path than the first intuitive approach. It doesn\'t add value for: clearly defined problems with one correct algorithm (use CoT instead), simple factual lookups (just ask), or time-sensitive tasks where exploration overhead exceeds the benefit. A useful heuristic: "Would a human expert consider multiple approaches before committing?" If yes, ToT; if no, CoT or direct prompting.' }
  ]
},

'18-2': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Model Capability Mapping', content: 'Map the capability differences between available AI models.\n\n**Step 1 — Ask Claude:** "Compare Claude Haiku, Sonnet, and Opus on these dimensions: reasoning depth, code generation quality, creative writing, following complex instructions, knowledge breadth, and speed. For each model, describe its sweet spot."\n\n**Step 2 — Test the same prompt** on Haiku and Sonnet:\nPrompt: "Design a system architecture for a real-time multiplayer game with 10,000 concurrent players. Include: technology stack, data flow, scaling strategy, and the 3 most important trade-offs."\n\n**Step 3 — Compare the responses.** Where does quality differ? Is the quality difference worth the cost difference for your use case?\n\n**Step 4 — Build a personal model selection matrix** for your most common tasks.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build an Intelligent Model Router', content: 'Implement a model router that selects the right AI for each task.\n\n**Step 1 — Define your routing criteria:**\n- Task complexity (simple → Haiku, complex → Sonnet)\n- Privacy requirements (sensitive → local model)\n- Speed requirement (real-time → Haiku, async → Sonnet)\n- Cost budget (high volume → Haiku, important decisions → Sonnet)\n\n**Step 2 — Ask Claude Code** to implement the router:\n```\nBuild a model_router function that:\n1. Takes a task description and metadata (privacy_level, response_time, importance, budget_tier)\n2. Applies routing rules to select the optimal model\n3. Logs the routing decision and reasoning\n4. Falls back to Haiku if routing is uncertain\n5. Includes a cost estimator for the selected model\n```\n\n**Step 3 — Test with 10 diverse task descriptions.** Are the routing decisions correct?\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review the routing logic. What task types will be systematically misrouted?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Task-Specific Model Benchmarking', content: 'Benchmark models on YOUR specific tasks, not generic benchmarks.\n\n**Step 1 — Create 5 test prompts** representative of your actual work.\n\n**Step 2 — Run each prompt** on both Haiku and Sonnet.\n\n**Step 3 — Evaluate each response** on: accuracy, completeness, usefulness for your specific context.\n\n**Step 4 — Calculate:** For each task type, what is the quality difference (0-100%) and the cost difference?\n\n**Step 5 — Find your "good enough threshold":** For which tasks is Haiku within 10% of Sonnet quality? Those tasks should use Haiku in production.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Dynamic Model Selection in Your Application', content: 'Add dynamic model selection to your AI application.\n\n**Step 1 — Take an existing AI feature** in your project or one from earlier in this course.\n\n**Step 2 — Implement a A/B testing framework:**\n```\nAdd A/B testing that:\n- Routes 20% of requests to Sonnet, 80% to Haiku\n- Measures output quality via user feedback or automated metrics\n- Tracks cost per request for each model\n- Generates a weekly report: quality vs cost for each model\n```\n\n**Step 3 — Run the A/B test** for at least 50 requests.\n\n**Step 4 — Analyse results:** Is Sonnet significantly better for this specific task? Is the cost premium justified?\n\n**Step 5 — Make a data-driven model selection decision** for this feature.' },

    { type: 'quiz', question: 'You\'re building a customer service bot that handles both simple FAQs and complex technical support. The most cost-efficient architecture is:', options: ['Use only Haiku for all requests to minimise cost', 'Use only Sonnet for all requests to maximise quality', 'Route simple FAQ requests to Haiku and complex technical issues to Sonnet based on intent classification', 'Randomly assign 50% to each model and average the results'], correct: 2, explanation: 'Tiered routing gives you cost efficiency where it\'s safe (FAQs have predictable, verifiable answers) and quality where it matters (complex technical support where wrong answers damage trust). Implementation: first classify the request type using a small, fast model or rule-based classifier; then route accordingly. Monitor: track when Haiku-handled requests escalate to human support (suggests misrouting or quality gap).' },

    { type: 'quiz', question: 'A new AI model is released claiming "10× better performance" on benchmarks. Should you immediately switch your production application to it?', options: ['Yes — benchmarks indicate real-world performance', 'No — evaluate it on your specific tasks first. General benchmarks often don\'t reflect task-specific performance, and "better" on a benchmark may not mean better for your use case', 'Yes if it\'s from a reputable provider', 'No — always wait 6 months for new models to stabilise'], correct: 1, explanation: 'Benchmark performance rarely translates directly to task-specific performance. Evaluate any new model by: (1) running your specific test prompts and comparing outputs, (2) checking whether the new model behaves differently on edge cases your application encounters, (3) testing performance and latency, (4) verifying cost. Only switch after you can confirm the new model outperforms the current one on your actual tasks, not just on published benchmarks.' }
  ]
},

'18-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Research Tool Comparison', content: 'Compare specialised research tools against general AI for academic research.\n\n**Step 1 — Ask Claude:** "Explain the purpose and strengths of these research tools: Perplexity, Elicit, Consensus, and Scite. For each: what type of research question is it best suited for? What can it do that Claude cannot?"\n\n**Step 2 — Test the same research question** across available tools:\nQuestion: "What does the research say about [a topic in your field]?"\n\n**Step 3 — Compare results:**\n- Source quality (peer-reviewed vs general web)\n- Citation accuracy\n- Ability to find contradictory evidence\n- Synthesis quality\n\n**Step 4 — Build a tool selection guide** for your specific research needs.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Systematic Literature Review with AI', content: 'Conduct a systematic literature review using AI research tools.\n\n**Step 1 — Define a specific research question** from your field.\n\n**Step 2 — Use specialised tools** (Elicit, Consensus, or Semantic Scholar) to find relevant papers.\n\n**Step 3 — For each paper found**, extract key information using Claude:\n```\nExtract from this paper abstract:\n- Research question\n- Methodology\n- Key findings\n- Sample size/scope\n- Limitations acknowledged\n- Confidence level in findings: High/Medium/Low (based on methodology)\n```\n\n**Step 4 — Synthesise across papers:**\n"Based on these paper extractions [paste them], synthesise the state of research on [question]. What is the consensus? What is disputed? What are the research gaps?"\n\n**Step 5 — Mandatory review:** Ask Claude: *"What important papers might this systematic review have missed? What should I search for to make this more complete?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Citation Verification', content: 'Build rigorous citation verification habits for AI-assisted research.\n\n**Step 1 — Take a Perplexity or AI research output** with 5+ citations.\n\n**Step 2 — Verify each citation:**\n1. Does the source actually exist? (Search for the exact title)\n2. Does the source say what\'s attributed to it? (Read the relevant section)\n3. Is the source as authoritative as implied?\n4. Is the source recent enough?\n\n**Step 3 — Calculate your verification rate:** What % of citations checked out fully? What % had issues?\n\n**Step 4 — Ask Claude:** "I found that [X%] of AI-sourced citations had problems of type [list them]. How should I adjust my research workflow to account for this citation reliability rate?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Research Database Building', content: 'Build a personal research database using AI-assisted curation.\n\n**Step 1 — Ask Claude Code** to design a research database system:\n```\nDesign a personal research database using Obsidian/markdown or a simple SQLite database:\n1. Paper/source entries: title, authors, date, abstract, key findings, tags, credibility score\n2. Connection mapping: which papers cite each other? Which contradict each other?\n3. Question tracking: which research questions does each paper address?\n4. Review scheduling: flag papers for re-review if new contradictory evidence emerges\n```\n\n**Step 2 — Set up the database** and add 10 papers/sources relevant to your work.\n\n**Step 3 — Create a monthly maintenance routine:** new papers to add, outdated entries to update.\n\n**Step 4 — Test the database** by answering a research question using it instead of starting fresh.' },

    { type: 'quiz', question: 'Scite shows that a paper you\'re citing has more "contradicting" citations than "supporting" citations. What should you do?', options: ['Remove the paper from your research — it\'s discredited', 'Investigate the contradicting papers: understand the methodological differences, read the contradiction context, and either update your analysis to acknowledge the controversy or find stronger supporting evidence', 'Cite more supporting papers to balance the ratio', 'Ignore the scite data — it doesn\'t reflect paper quality'], correct: 1, explanation: 'Contradicting citations are valuable information, not automatic disqualifiers. Many legitimate findings are contested in science. Investigate: what specifically are the contradicting papers challenging? Is it the methodology, the generalizability, or the interpretation? Some contradictions reveal real weaknesses in the research; others are methodological disagreements with no clear winner. Your job: acknowledge the controversy accurately in your own research, rather than either ignoring it or abandoning the source.' },

    { type: 'quiz', question: 'Elicit finds 8 papers relevant to your research question but you only have time to read 2 thoroughly. Which 2 should you prioritise?', options: ['The 2 most recent papers', 'The 2 with the most citations', 'The 2 most directly addressing your specific question with the strongest methodology — ask Claude to help select based on abstract analysis', 'The 2 that best support your hypothesis'], correct: 2, explanation: 'Prioritise papers that: (1) directly address your specific question (not just related topics), (2) have strong methodology (large samples, controls, peer-reviewed), and (3) are either the foundational study in the area or the most recent comprehensive review. Citation count is a proxy for influence, not quality. Recency matters for fast-moving fields. Ask Claude: "Based on these abstracts, which 2 papers would most advance my understanding of [specific question]?"' }
  ]
},

'18-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — RAG Concept Deep Dive', content: 'Understand Retrieval-Augmented Generation (RAG) at a practical level.\n\n**Step 1 — Ask Claude:** "Explain RAG to someone who has never heard of it. What problem does it solve? How does it work at a high level? What are the most common use cases? What are its limitations?"\n\n**Step 2 — Ask the follow-up:** "Compare RAG to: (1) fine-tuning a model on your data, (2) prompt engineering with pasted context, (3) a vector database. When is each approach better?"\n\n**Step 3 — Map RAG to your use case:** Do you have a knowledge management problem that RAG would solve? What data would you index?\n\n**Step 4 — Ask Claude:** "For [your use case], would RAG be the right approach or would one of the alternatives be simpler and adequate?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build a Simple RAG System', content: 'Build a basic RAG system over your own documents.\n\n**Step 1 — Ask Claude Code** to build a simple RAG system:\n```\nBuild a simple RAG system in Python:\n1. Document ingestion: read markdown/text files from a folder, split into chunks\n2. Embedding: use the Anthropic API (or sentence-transformers for free local embeddings) to create embeddings\n3. Storage: save embeddings in a simple FAISS index\n4. Query: embed the user\'s question, find the 3 most similar chunks, pass them as context to Claude for answer generation\n5. CLI interface: query the system from the command line\n```\n\n**Step 2 — Feed your own documents** (notes, documentation, reports) into the system.\n\n**Step 3 — Test with 5 questions** that should be answerable from your documents.\n\n**Step 4 — Mandatory review:** Ask Claude: *"Review this RAG implementation. What are the 3 most common failure modes in simple RAG systems that I should test for?"*' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — RAG Quality Evaluation', content: 'Evaluate and improve your RAG system\'s retrieval quality.\n\n**Step 1 — Ask Claude:** "What are the most common ways RAG systems fail to retrieve the right context? For each failure mode, what improvement would fix it?"\n\n**Step 2 — Test these failure modes** in your RAG system:\n- Semantic mismatch: question uses different vocabulary than the document\n- Chunking problems: answer spans two chunks\n- Irrelevant retrieval: similar-sounding but unrelated content retrieved\n\n**Step 3 — For each failure**, implement one improvement:\n- Semantic mismatch: try query expansion (have Claude rephrase the question before embedding)\n- Chunking: increase chunk overlap\n- Irrelevant retrieval: add metadata filtering\n\n**Step 4 — Measure improvement** — does the fix help?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Personal Knowledge Engine', content: 'Build a personal knowledge engine over your accumulated notes and documents.\n\n**Step 1 — Identify all your knowledge sources:**\n- Personal notes (Obsidian, Notion, markdown files)\n- Saved articles or documents\n- Meeting notes\n- Research briefs\n\n**Step 2 — Build an ingestion pipeline** that indexes all of these sources:\n```\n1. Collect all documents from configured folders\n2. Convert non-markdown formats to text\n3. Chunk with appropriate sizes for each document type\n4. Embed and store in FAISS\n5. Update index when new documents are added\n```\n\n**Step 3 — Create a query interface** that feels natural to use.\n\n**Step 4 — Test the knowledge engine** by asking questions about topics you\'ve researched in the past. Does it surface relevant material you\'d forgotten?' },

    { type: 'quiz', question: 'Your RAG system retrieves 3 document chunks for a query but the actual answer is in a 4th chunk it missed. What is the most likely cause?', options: ['The embedding model is broken', 'The relevant chunk may have low semantic similarity to the query vocabulary despite containing the answer — try hybrid search (semantic + keyword matching) or increase k (retrieve more chunks)', 'The chunk was too long to embed', 'The FAISS index is corrupted'], correct: 1, explanation: 'Retrieval failure is often a vocabulary mismatch problem. "What are the trade-offs of microservices?" might miss a chunk that says "disadvantages of service-oriented architecture" because the embedding spaces are similar but not identical. Solutions: (1) retrieve more chunks (top-10 instead of top-3) and let the LLM filter; (2) hybrid search combining semantic similarity with BM25 keyword matching; (3) query expansion — have the LLM generate alternative phrasings of the question before retrieval.' },

    { type: 'quiz', question: 'You build a RAG system over company documentation. An employee asks a question and gets an outdated answer from a document that was superseded. What went wrong and how do you prevent it?', options: ['RAG cannot handle document updates', 'The outdated document was still in the index — implement document versioning: when a document is updated, remove the old embeddings and add the new ones; add document date metadata so the LLM can prefer recent sources', 'The user should check document dates manually', 'Use a smaller chunk size to avoid storing outdated content'], correct: 1, explanation: 'RAG systems that index static snapshots of documentation quickly become stale. Prevention: (1) implement an update pipeline that detects changed files and refreshes their embeddings; (2) store document metadata (date, version, supersedes) and pass it to the LLM; (3) instruct the LLM to prefer more recent sources when dates differ; (4) add a "last updated" field to your document store and display it alongside answers so users can judge relevance.' }
  ]
},

'18-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — AI Agent Anatomy', content: 'Understand the components of a working AI agent.\n\n**Step 1 — Ask Claude:** "Explain the architecture of an AI agent. What are the core components: perception, reasoning, planning, action, and memory? How do they interact? Give a concrete example of a simple agent executing a task."\n\n**Step 2 — Map a real AI agent** you\'ve used (Claude Code, task-master-ai, etc.) to this architecture:\n- Perception: what inputs does it take?\n- Reasoning: how does it make decisions?\n- Planning: how does it break down tasks?\n- Action: what tools can it use?\n- Memory: what does it remember across steps?\n\n**Step 3 — Ask Claude:** "What are the failure modes of each agent component? For each, how do you detect and recover from failures?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Design a Custom AI Agent', content: 'Design a custom AI agent for a real task you need to automate.\n\n**Step 1 — Choose a complex multi-step task** you currently do manually.\n\n**Step 2 — Ask Claude to help design the agent:**\n```\nDesign an AI agent for this task: [describe the task]\n\nFor the design, specify:\n1. Input: what triggers the agent and what information it receives\n2. Tools needed: what capabilities does it need?\n3. Decision points: where does it need to choose between paths?\n4. Output: what does it produce?\n5. Failure modes: what can go wrong and how should it handle each?\n6. Human oversight: at which points should it check with a human?\n```\n\n**Step 3 — Review the design.** Is every tool listed actually available?\n\n**Step 4 — Implement a minimal version** of the agent using Claude Code.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Test Agent Reliability', content: 'Systematically test an AI agent\'s reliability.\n\n**Step 1 — Take the agent you designed** in Workshop B.\n\n**Step 2 — Test these reliability scenarios:**\n- Happy path: everything works as expected\n- Tool failure: one tool returns an error mid-task\n- Ambiguous input: the input doesn\'t give enough information to complete the task\n- Very long task: the task requires more steps than typical\n- Edge case: unusual input that wasn\'t considered in the design\n\n**Step 3 — Document how the agent behaves** in each scenario.\n\n**Step 4 — Improve the agent** based on the failures found.\n\n**Step 5 — Mandatory review:** Ask Claude: *"Given these test results [describe what happened], what are the remaining reliability risks before I use this agent in production?"*' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Human-in-the-Loop Agent', content: 'Build an agent with appropriate human oversight.\n\n**Step 1 — Identify the highest-risk actions** your agent can take.\n\n**Step 2 — Ask Claude Code** to implement human-in-the-loop checkpoints:\n```\nModify the agent to add human checkpoints:\n1. Before any irreversible action: pause and ask for confirmation\n2. When confidence is low: surface the uncertainty and ask for guidance\n3. After completing each major phase: summarise what was done and ask to continue\n4. If an error occurs: explain the error and ask how to proceed\n\nThe checkpoint should: describe what\'s about to happen, show relevant context, offer: proceed / modify / abort.\n```\n\n**Step 3 — Test the checkpoints** — do they trigger at the right moments?\n\n**Step 4 — Evaluate the balance:** Are there too many checkpoints (disrupting autonomous operation) or too few (allowing risky unchecked actions)?' },

    { type: 'quiz', question: 'An AI agent is tasked with "reorganise my project files" and begins moving and deleting files without confirmation. What is the critical design flaw?', options: ['The agent is too slow at processing files', 'No human-in-the-loop for irreversible actions: file deletion is permanent, and file movement can be disruptive. The agent should always preview proposed changes and require confirmation before executing them', 'The agent should use a different file system API', 'File operations should be handled by a different tool'], correct: 1, explanation: 'Irreversible actions require human confirmation by design, not as an afterthought. File deletion cannot be undone (without backup). File movement can break dependencies (code imports, scripts referencing paths). An agent that "reorganises" without confirmation is dangerous regardless of how intelligent its plan is. The pattern for any agent handling irreversible operations: plan → show the plan → wait for explicit approval → execute. This adds one interaction but prevents disasters.' },

    { type: 'quiz', question: 'Your AI agent gets stuck in a loop, repeatedly trying the same failed action. What design element would have prevented this?', options: ['A faster model', 'A retry limit with escalation: after N failed attempts at the same action, the agent should stop trying and either try an alternative approach or escalate to human review', 'More detailed instructions', 'A different tool for that action'], correct: 1, explanation: 'Infinite loops and stuck states are a class of agent reliability problems. Prevention: (1) maximum retry count for any single action (e.g., 3 attempts), (2) step-level timeout (each action has a time limit), (3) loop detection (if the same action with the same parameters has been tried before, don\'t try again), (4) escalation path (when stuck, the agent should surface the problem to a human rather than continuing to fail silently).' }
  ]
},

'18-6': {
  addMinutes: 25,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Knowledge Engine Architecture', content: 'Design your personal knowledge engine before building it.\n\n**Step 1 — Inventory your knowledge sources:**\n- How many documents/notes do you have? (rough count)\n- What formats? (markdown, PDF, web pages, emails)\n- How are they currently organised? (folder structure, tags)\n- How do you currently search them?\n\n**Step 2 — Define your use case precisely:** What questions do you want your knowledge engine to answer? "Search my notes" is too vague. "Answer questions about technical decisions I\'ve made in the last year" is specific.\n\n**Step 3 — Ask Claude to design the architecture:**\n"Design a personal knowledge engine for [your use case]. What indexing strategy, chunking approach, and query interface would best serve this specific use case?"\n\n**Step 4 — Validate feasibility:** Can you build this in [your time budget] with your current skills? What\'s the MVP version?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build and Index', content: 'Build and populate your personal knowledge engine.\n\n**Step 1 — Ask Claude Code** to implement the ingestion pipeline based on your architecture design.\n\n**Step 2 — Start with a subset** of your documents (50-100) for initial testing.\n\n**Step 3 — Run the ingestion.** Does it complete without errors? How long does it take?\n\n**Step 4 — Query the engine** with 10 test questions that your documents should be able to answer.\n\n**Step 5 — Measure retrieval quality:** For each question, rate 1-5 whether the retrieved chunks were relevant.\n\n**Step 6 — Improve the configuration** (chunk size, overlap, number of results retrieved) based on the quality assessment.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Query Interface Design', content: 'Design a query interface that makes your knowledge engine actually usable.\n\n**Step 1 — Ask Claude:** "What makes a knowledge engine interface actually useful vs technically correct but frustrating to use? What interface elements are most important?"\n\n**Step 2 — Design your interface:**\n- Query input (how do you enter questions?)\n- Result display (how are answers shown?)\n- Source display (which documents were used?)\n- Confidence indicator (how certain is the answer?)\n- Navigation (can you open the source documents?)\n\n**Step 3 — Ask Claude Code** to implement the interface based on your design.\n\n**Step 4 — Use the engine for one week** for real work. What friction points emerge?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Expand and Maintain', content: 'Scale your knowledge engine and establish maintenance routines.\n\n**Step 1 — Expand the index** to include all your relevant documents.\n\n**Step 2 — Set up automatic updates:** When new documents are added to your knowledge sources, they should automatically be indexed.\n\n**Step 3 — Establish a maintenance routine:**\n- Monthly: check that the index is current\n- Quarterly: review query logs for common questions that produce poor results\n- Annually: evaluate whether the architecture still fits your needs\n\n**Step 4 — Measure actual usage impact:** After one month, has the knowledge engine changed how you work? What would you do differently?' },

    { type: 'quiz', question: 'Your knowledge engine returns an answer that confidently cites a specific document, but when you check the document, the cited information isn\'t there. What is happening?', options: ['The document was deleted from the index', 'Hallucination: the LLM may have generated a plausible-sounding citation that doesn\'t match actual retrieved content. Always display the exact retrieved chunks alongside the answer', 'The retrieval system has a bug', 'The document format wasn\'t parsed correctly'], correct: 1, explanation: 'RAG systems can still hallucinate citations and content even when documents are retrieved. The LLM might: reference a document by name but make up the specific detail, generate a plausible quote that isn\'t in the source, or misattribute content from one document to another. Mitigation: always display the actual retrieved text chunks alongside the answer so users can verify. Ideally, the interface shows: "Based on this passage from [document]: [exact quote]" rather than just an answer.' },

    { type: 'quiz', question: 'Your knowledge engine works well on recent documents but poorly on documents from 3 years ago. What is the most likely cause?', options: ['Older documents use outdated language that models can\'t understand', 'Old documents may use different terminology or writing styles — the embedding model creates different representations for older vocabulary, reducing semantic match with modern query language', 'The embedding model was trained after those documents were written', 'Older documents are too long to be indexed correctly'], correct: 1, explanation: 'Vocabulary drift affects retrieval quality. Concepts described with older terminology may not match the embedding space for modern query language, even if the concepts are the same. For example, "machine learning" queries might not retrieve documents about "artificial intelligence" from the early 2010s. Mitigation: (1) query expansion — have the LLM generate older synonyms before retrieval, (2) add a date-aware search layer, (3) tag old documents with modern synonym annotations during ingestion.' }
  ]
},

'18-7': {
  addMinutes: 25,
  sections: [
    { type: 'workshop', tag: 'BUILD', title: 'Workshop A — Tool Architecture and Planning', content: 'Plan your AI research tool before writing any code.\n\n**Step 1 — Define the exact problem** your research tool solves. Spend 10 minutes on this — the clearer the problem, the simpler the tool.\n\n**Step 2 — Ask Claude** to help you choose the right architecture:\n```\nHelp me choose the right architecture for this AI research tool:\n[describe your tool]\n\nCompare these approaches:\n1. Simple LLM wrapper (just call Claude with a system prompt)\n2. RAG over a document corpus\n3. Agentic loop with web search tools\n4. Hybrid (which combination?)\n\nFor my use case, which approach delivers the most value with the least complexity?\n```\n\n**Step 3 — Choose the simplest architecture** that meets your requirements.\n\n**Step 4 — Write a one-page technical spec** before starting development.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Build, Test, and Iterate', content: 'Execute the full development lifecycle for your research tool.\n\n**Step 1 — Build the MVP** using Claude Code.\n\n**Step 2 — Define your test corpus:** 20 research questions the tool should be able to answer.\n\n**Step 3 — Run all 20 questions.** Score each answer: Correct (2), Partially correct (1), Wrong (0).\n\n**Step 4 — Analyse failures:** For wrong answers, is the problem retrieval (right information wasn\'t found), generation (right information was found but answer was wrong), or scope (question was outside the tool\'s design)?\n\n**Step 5 — Fix the top failure mode** and re-test the affected questions.' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — Performance and Cost Optimization', content: 'Optimise your research tool for production use.\n\n**Step 1 — Measure baseline performance:**\n- Average response time (seconds)\n- Average cost per query (tokens × price)\n- P95 response time (95th percentile)\n\n**Step 2 — Profile where time and cost are spent:** Is most time in retrieval, embedding, or generation?\n\n**Step 3 — Apply the top optimisations based on the profile:**\n- Expensive generation → switch to a cheaper model or shorter prompts\n- Slow retrieval → optimise FAISS configuration or add a cache\n- Slow embedding → use a local embedding model instead of API calls\n\n**Step 4 — Re-measure after each optimisation.** Did it improve the bottleneck without degrading quality?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Documentation and Handoff', content: 'Document your research tool for long-term maintainability.\n\n**Step 1 — Ask Claude Code** to generate documentation:\n```\nCreate documentation for this research tool:\n1. README.md: what it does, how to install, how to use (with examples)\n2. ARCHITECTURE.md: how it works technically, component diagram, data flow\n3. OPERATIONS.md: how to update the knowledge base, troubleshoot common issues, monitor performance\n4. DEVELOPMENT.md: how to run tests, add new features, contribute changes\n```\n\n**Step 2 — Review each document** for accuracy — AI-generated docs often need factual corrections.\n\n**Step 3 — Publish the tool** (GitHub, or internal deployment).\n\n**Step 4 — Onboard one user:** Have a colleague use the tool and document their questions. These questions become FAQ additions to the docs.' },

    { type: 'quiz', question: 'You build a research tool that consistently returns high-quality answers during testing but produces poor answers in production. What is the most likely cause?', options: ['Production servers are slower and reduce AI quality', 'Distribution shift: production queries differ from your test corpus — real users ask different types of questions, use different vocabulary, or explore edge cases you didn\'t anticipate', 'The AI model behaviour changed', 'You need to increase the server capacity'], correct: 1, explanation: 'Test data rarely represents production query distribution perfectly. Your test corpus was designed by you, reflecting how you think about the problem. Real users bring unexpected question formulations, unusual topics, adversarial inputs, and use cases you didn\'t anticipate. Fix: (1) collect production queries and add them to your test corpus; (2) monitor production answer quality metrics; (3) regularly review a sample of production queries for quality; (4) add a user feedback mechanism.' },

    { type: 'quiz', question: 'A colleague says "just use Perplexity" instead of building a custom research tool. When is building your own tool genuinely worth it?', options: ['Always — custom tools are always better', 'When Perplexity cannot do what you need: private data (Perplexity accesses only public web), domain-specific retrieval quality, integration with internal systems, or cost efficiency at high volume', 'When you want to learn how to build it', 'Never — use existing tools always'], correct: 1, explanation: 'Build vs buy has a clear framework: build when existing tools fundamentally cannot meet your requirements. Perplexity is excellent for public web research. Building your own tool adds value when: the data is private (internal documents, proprietary databases), you need integration with internal systems, the domain requires specialised retrieval (medical literature, legal documents, code), or you\'re running at a volume where per-query costs make a custom system cheaper. If Perplexity meets your needs, use it — your engineering time is valuable.' }
  ]
},

'19-2': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — AI Travel Research Drill', content: 'Plan a real trip using AI research tools.\n\n**Step 1 — Choose a real trip you\'re planning or want to plan.**\n\n**Step 2 — Ask Claude to help with the research framework:**\n```\nHelp me research a trip to [destination] for [duration] with these preferences:\n- Budget: [range]\n- Travel style: [adventure/relaxed/cultural/food-focused]\n- Time of year: [month]\n\nWhat are the most important things to research? Structure this as a research checklist.\n```\n\n**Step 3 — Work through the checklist** using Claude and Perplexity.\n\n**Step 4 — Verify time-sensitive information** (visa requirements, seasonal closures, prices) from official sources — not AI.\n\n**Step 5 — Ask Claude:** "What did I forget to research? What commonly surprises first-time visitors to [destination]?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI Itinerary Builder', content: 'Build a detailed AI-assisted itinerary.\n\n**Step 1 — Specify the trip parameters** you\'ve researched.\n\n**Step 2 — Ask Claude to draft an itinerary:**\n```\nCreate a detailed [X-day] itinerary for [destination].\n\nConstraints:\n- Accommodation: [area/type]\n- Daily budget: [amount]\n- Must-see: [your list]\n- Avoid: [things you don\'t want]\n- Travel pace: [1-2 major things per day or packed]\n\nFor each day:\n- Morning, afternoon, evening activities\n- Estimated travel time between locations\n- Meal suggestions (price range, type)\n- Practical tips for each activity\n```\n\n**Step 3 — Evaluate the itinerary** for logistics — are the locations geographically sensible? Is the pace realistic?\n\n**Step 4 — Verify opening times and prices** for 3 specific activities from official sources.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Trip Risk Assessment', content: 'Use AI to identify and prepare for travel risks.\n\n**Step 1 — Ask Claude:** "For a trip to [destination] during [time period], what are the main risks: safety, health, weather, political, logistical? For each, what preparation is recommended?"\n\n**Step 2 — Check official sources** for any high-risk items Claude identifies:\n- Travel advisories: your government\'s travel advisory for the destination\n- Health requirements: official public health guidance\n- Visa requirements: official embassy or government website\n\n**Step 3 — Create a pre-departure checklist** covering the identified risks.\n\n**Step 4 — Ask Claude:** "What emergency contacts and information should I have saved before this trip? Create a reference card I can keep on my phone."' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Trip Document Pack', content: 'Create a complete trip documentation package using AI assistance.\n\n**Step 1 — Ask Claude Code** to create a trip document template:\n```\nCreate a trip document package for [destination]:\n1. Trip overview (one-page summary)\n2. Day-by-day itinerary (detailed)\n3. Key contacts (accommodation, emergency, transportation)\n4. Budget tracker (planned vs actual)\n5. Packing list (customised for [destination and activities])\n6. Language reference (key phrases if non-English destination)\n7. Health and safety info\n```\n\n**Step 2 — Fill in each document** with your actual trip details.\n\n**Step 3 — Share the documents** with travel companions or emergency contacts.\n\n**Step 4 — After the trip**, update the documents with actual costs and experiences — this becomes a reference for future trips.' },

    { type: 'quiz', question: 'Claude says a particular restaurant "is one of the best in [city]." You plan your trip around eating there. What verification should you do?', options: ['Nothing — Claude knows about restaurants', 'Verify independently: check recent reviews (AI knowledge may be outdated), confirm it\'s still open, check current reservation requirements — restaurant situations change and AI training data is not real-time', 'Call the restaurant to confirm', 'Only verify if the restaurant is expensive'], correct: 1, explanation: 'Restaurant recommendations are time-sensitive: restaurants close, change chefs, decline in quality, or require reservations that didn\'t exist before. Claude\'s restaurant knowledge has a cutoff date. For any specific recommendation that affects your plans: check recent reviews (TripAdvisor, Google, Yelp from the last 6 months), verify it\'s still operating, and check current booking requirements. This takes 3 minutes and prevents a planned meal from being a disappointment.' },

    { type: 'quiz', question: 'You use AI to research visa requirements for your destination and it says "no visa required for your passport." Is it safe to rely on this?', options: ['Yes — visa requirements rarely change', 'No — always verify visa requirements from your destination country\'s official embassy or immigration website; visa requirements change and AI knowledge may be outdated', 'Yes if you double-check with a second AI tool', 'Only verify if you\'ve had visa issues before'], correct: 1, explanation: 'Visa requirements are high-stakes and time-sensitive — incorrect information can result in being denied boarding or entry to a country. Always verify from official sources: (1) the destination country\'s official immigration or embassy website, (2) your own country\'s foreign affairs/state department travel guidance, (3) the airline\'s TIMATIC system for their boarding decision. AI may have outdated information, especially for countries with frequent policy changes.' }
  ]
},

'19-3': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Personal Finance AI Audit', content: 'Use AI to audit your personal financial situation.\n\n**Step 1 — Gather your key financial numbers** (approximate is fine):\n- Monthly income\n- Fixed monthly expenses (rent, subscriptions, etc.)\n- Variable monthly expenses (food, entertainment)\n- Savings rate (%)\n- Debt: type, amount, interest rate\n- Emergency fund (months of expenses)\n\n**Step 2 — Ask Claude:**\n"Review my financial situation [paste numbers]. What are the most important improvements to make? Where am I doing well? What financial risks am I exposed to?"\n\n**Step 3 — Evaluate Claude\'s assessment.** Does it identify the right priorities?\n\n**Step 4 — Ask:** "What is the one change that would have the biggest impact on my financial position in the next 12 months?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Budget Building with AI', content: 'Build a personal budget using AI assistance.\n\n**Step 1 — Ask Claude to help structure your budget:**\n```\nHelp me build a monthly budget for someone with:\n- Take-home income: [amount]\n- Fixed expenses: [list with amounts]\n- Financial goals: [save for X, pay off Y, invest in Z]\n\nCreate a zero-based budget that:\n1. Covers all fixed expenses\n2. Allocates to goals\n3. Leaves realistic amounts for variable spending\n4. Identifies 2-3 expenses to reduce\n```\n\n**Step 2 — Review the proposed budget** honestly. Is it realistic for how you actually live?\n\n**Step 3 — Ask Claude:** "If I stick to this budget for 12 months, what will my financial position be? What will I have achieved?"\n\n**Step 4 — Track actual spending** for one week and compare to the budget.' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Financial Concept Explainer', content: 'Use AI to understand financial concepts you\'ve been avoiding.\n\n**Step 1 — Identify financial concepts** you\'ve been meaning to understand: investment accounts (ISA/401k/IRA), compound interest, index funds, tax efficiency, insurance.\n\n**Step 2 — For each concept**, ask Claude to explain it at your level:\n"Explain [concept] as if I know basic personal finance but haven\'t learned this specific topic. Use a concrete example with real numbers."\n\n**Step 3 — Ask the follow-up question:** "How does understanding [concept] change what I should do with [my specific situation]?"\n\n**Step 4 — Identify one financial action** you\'ve been avoiding due to uncertainty. Does understanding the concept make you ready to take that action?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Financial Goal Planning', content: 'Use AI to create a concrete plan for a specific financial goal.\n\n**Step 1 — Choose a specific financial goal:** buy a house, retire by X, pay off debt, build an emergency fund.\n\n**Step 2 — Ask Claude for a goal plan:**\n```\nCreate a specific plan to [your goal].\n\nMy situation:\n- Current savings: [amount]\n- Monthly surplus (after expenses): [amount]\n- Timeline: [years]\n- Risk tolerance: [conservative/moderate/aggressive]\n\nProvide:\n1. Monthly savings target\n2. Investment approach for this goal\n3. Milestones to track progress\n4. What would delay or derail this goal\n5. One-year action plan with specific steps\n```\n\n**Step 3 — Evaluate the plan.** Is the monthly savings target achievable? Are the milestones motivating?\n\n**Step 4 — Important disclaimer:** Verify all specific investment advice with a qualified financial advisor before acting.' },

    { type: 'quiz', question: 'Claude gives you specific investment advice: "Put 60% in global index funds and 40% in bonds." Should you follow this advice?', options: ['Yes — this is standard diversified portfolio advice', 'Use it as a starting point for research, not as a prescription. AI financial advice doesn\'t account for your tax situation, risk tolerance, existing investments, or local regulations — consult a financial advisor for personalised recommendations', 'No — all AI financial advice is wrong', 'Yes if you\'re under 50'], correct: 1, explanation: 'AI financial advice is general information, not personalised financial advice. It cannot account for: your specific tax situation and tax-advantaged accounts available in your country, your existing investment portfolio and rebalancing needs, your actual risk tolerance (not stated preference), life events that affect your financial timeline, or jurisdiction-specific regulations. Use AI to understand concepts and prepare questions for a financial advisor, not to make specific investment decisions.' },

    { type: 'quiz', question: 'You ask Claude to calculate how long it will take to pay off your debt at various payment amounts. Claude provides calculations. What should you verify?', options: ['The calculations are correct if Claude shows its work', 'Verify the math independently: AI can make arithmetic errors, especially with compound interest calculations. Use a debt payoff calculator from a bank or financial site to confirm the numbers', 'Only verify if the numbers seem surprising', 'The calculation methodology, not the specific numbers'], correct: 1, explanation: 'Financial calculations with compound interest are complex enough that AI errors are meaningful. An error in the interest rate used, compound frequency assumed, or calculation formula could produce a result that\'s off by months or thousands of dollars. For any financial calculation that affects a real decision: (1) have Claude explain the formula it used, (2) verify with a dedicated financial calculator (most bank websites have them), (3) for large decisions, have an accountant or financial advisor verify.' }
  ]
},

'19-4': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Health Information Research', content: 'Use AI for health research while maintaining appropriate skepticism.\n\n**Step 1 — Ask Claude:** "What are the appropriate ways to use AI for health information? What are the situations where AI health information is dangerous? How should I validate AI health information?"\n\n**Step 2 — Test AI health information quality:** Ask Claude a specific health question you have.\n\n**Step 3 — Evaluate the response:**\n- Did Claude recommend consulting a healthcare provider?\n- Were the uncertainty and limitations clear?\n- Is the information consistent with reputable health sources (Mayo Clinic, NHS, medical journals)?\n\n**Step 4 — Ask Claude:** "For this health question, what are the authoritative sources I should check to verify this information?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Health and Wellness Habit Tracking', content: 'Build an AI-assisted health habit tracking system.\n\n**Step 1 — Identify 3 health habits** you want to build or improve.\n\n**Step 2 — Ask Claude to design a tracking system:**\n```\nDesign a health habit tracking system for:\nHabits: [list them]\nMy current baseline: [where I am now]\nGoal: [where I want to be in 90 days]\n\nCreate:\n1. Daily tracking template (simple, under 2 minutes to complete)\n2. Weekly review questions\n3. How to identify if I\'m making progress\n4. What to do when I break the habit chain\n```\n\n**Step 3 — Set up the tracking system** (simple text file, spreadsheet, or app).\n\n**Step 4 — After 2 weeks**, do the weekly review with Claude\'s help: "Here\'s my 2-week tracking data [paste it]. What patterns do you see? What should I adjust?"' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Wellbeing Assessment', content: 'Use AI to assess and improve your overall wellbeing.\n\n**Step 1 — Ask Claude to guide a wellbeing assessment:**\n"Guide me through a comprehensive wellbeing check-in. Ask me about: physical health habits, mental wellbeing, social connections, work satisfaction, and life balance. For each area, assess my current state and suggest 1-2 improvements."\n\n**Step 2 — Answer each question honestly** — this is for your own use, not for anyone else.\n\n**Step 3 — Identify the one area** where a small improvement would have the biggest impact on your overall wellbeing.\n\n**Step 4 — Design one concrete habit** to address that area.\n\n**Step 5 — Important note:** If any wellbeing area raises serious concerns (mental health, medical symptoms), prioritise professional support over AI assistance.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — AI Health Information Workflow', content: 'Build a responsible workflow for using AI in health decisions.\n\n**Step 1 — Create a Health AI Usage Policy for yourself:**\n```\n## My Health AI Policy\n\n### When AI is appropriate\n- General health education\n- Understanding medical terms\n- Research before a doctor\'s appointment\n- Habit and lifestyle planning\n\n### When to always consult a professional\n- Symptoms that could indicate serious conditions\n- Medication dosages or interactions\n- Mental health concerns\n- Any decision with significant health consequences\n\n### How I verify AI health information\n1. Check reputable health sources (NHS, Mayo Clinic, etc.)\n2. Bring questions to my next medical appointment\n3. Never self-diagnose based on AI information alone\n```\n\n**Step 2 — Review the policy with Claude:** "Review this health AI usage policy. Am I being too restrictive? Too permissive? What important situations am I missing?"' },

    { type: 'quiz', question: 'You describe symptoms to Claude and it says "this could be condition X." You are worried and want to confirm. What is the right next step?', options: ['Ask Claude more detailed questions until you get a definitive diagnosis', 'See a healthcare provider: AI symptom analysis is explicitly not medical advice, cannot physically examine you, doesn\'t have your medical history, and should never replace professional medical diagnosis', 'Search online for more information about condition X', 'Wait and see if the symptoms worsen'], correct: 1, explanation: 'AI cannot diagnose medical conditions. When Claude says "this could be condition X," it means: based on the described symptoms, condition X is a possibility that should be evaluated by a professional who can: physically examine you, order appropriate tests, review your full medical history, and apply clinical judgement. Using AI symptom descriptions to self-diagnose and then either treat yourself or worry without seeking care are both poor outcomes. AI can help you understand symptoms and prepare questions for a doctor — not replace the doctor.' },

    { type: 'quiz', question: 'Claude recommends a specific supplement for a health goal. What should you do before purchasing it?', options: ['Buy it — Claude has good health information', 'Research the supplement\'s evidence base independently (check systematic reviews, not just company claims) and discuss with a healthcare provider if you take any medications', 'Ask Claude to confirm the recommendation', 'Check the price and brand only'], correct: 1, explanation: 'Supplement recommendations require independent verification because: (1) the evidence base varies enormously — some supplements have strong evidence, most have weak evidence, some are harmful; (2) supplements can interact with medications; (3) "natural" doesn\'t mean safe or effective; (4) the supplement industry has less regulatory oversight than medications. Check: a reputable health information source for the specific supplement, and discuss with your doctor if you take any medications or have health conditions.' }
  ]
},

'19-5': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — AI Learning Acceleration Drill', content: 'Use AI to learn a new skill 3× faster.\n\n**Step 1 — Choose something you want to learn:** a programming language, a musical concept, a historical period, a professional skill.\n\n**Step 2 — Ask Claude to create a personalised learning plan:**\n```\nCreate a learning plan for [topic].\n\nMy background: [what I already know that\'s related]\nGoal: [what specifically I want to be able to do]\nTime available: [hours per week]\nLearning style: [prefer examples/theory/practice/conversation]\n\nPlan:\n1. What to learn in what order (dependencies)\n2. Specific resources for each stage\n3. How to practice effectively\n4. Milestones to know you\'re progressing\n5. Common misconceptions to avoid\n```\n\n**Step 3 — Start with the first item** on the plan today.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — AI Tutoring Session', content: 'Have a deep AI tutoring session on a topic you\'re struggling with.\n\n**Step 1 — Identify a concept** you\'ve tried to learn but don\'t fully understand.\n\n**Step 2 — Use the Socratic tutoring approach with Claude:**\n```\nTutor me on [concept] using the Socratic method.\nDon\'t explain everything — ask me questions to discover what I understand and what I\'m missing.\nStart with: what do I already know about [concept]?\n[Answer each question]\nAfter 10 exchanges, summarise my current understanding and the specific gaps.\n```\n\n**Step 3 — Work through the tutoring session** honestly — admit confusion, ask follow-up questions.\n\n**Step 4 — Test your understanding** by explaining the concept back to Claude in your own words.\n\n**Step 5 — Ask Claude:** "Where is my explanation wrong or incomplete? What\'s the most important thing I still haven\'t grasped?"' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Spaced Repetition with AI', content: 'Use AI to build a spaced repetition learning system.\n\n**Step 1 — Ask Claude:** "Explain spaced repetition and how it accelerates memory retention. How do I apply this principle with AI assistance rather than flashcard software?"\n\n**Step 2 — For something you\'re learning**, create 10 "cards" (questions and answers) using Claude:\n"Create 10 questions and answers that cover the key concepts of [topic]. Format as Q: [question] / A: [answer]. Make the questions test understanding, not just recall."\n\n**Step 3 — Test yourself** on the 10 questions.\n\n**Step 4 — Mark which you got right** and ask Claude to schedule the next review: "I knew: [list]. I didn\'t know: [list]. When should I review each, and what additional explanation do I need for the ones I missed?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Build a Personal Learning System', content: 'Create a systematic AI-assisted learning system for ongoing development.\n\n**Step 1 — Identify your learning goals** for the next 6 months across 2-3 areas.\n\n**Step 2 — Ask Claude to design a learning system:**\n```\nDesign a personal learning system for these goals:\n[list your goals]\n\nTime available: [hours per week total]\n\nDesign:\n1. How to allocate time across goals\n2. Learning activities for each goal (ratio of reading/practice/review)\n3. How to measure progress\n4. When to adjust the plan\n5. How to stay motivated when progress feels slow\n```\n\n**Step 3 — Implement the system** and run it for 2 weeks.\n\n**Step 4 — Evaluate:** Are you making progress? Is the system sustainable? What would you change?' },

    { type: 'quiz', question: 'You ask Claude to teach you machine learning and it gives you a comprehensive explanation of neural networks. You understand it immediately. What should you do next?', options: ['Move on to the next topic — you understand it', 'Apply it immediately: true understanding comes from using a concept, not just reading about it. Build a simple neural network, work through an example, or explain it to someone else — this reveals gaps that reading doesn\'t', 'Read the explanation again for reinforcement', 'Ask Claude for an even more detailed explanation'], correct: 1, explanation: 'The illusion of understanding from reading is one of the most common learning traps. You understand an explanation without necessarily being able to apply the concept to new problems. The only test of real understanding: solve novel problems without referring back to the explanation. For machine learning: implement a neural network from scratch, apply it to a dataset, and debug why it\'s not working. These exercises reveal whether you truly understand or just recognise the explanation.' },

    { type: 'quiz', question: 'Claude tutors you on a concept and you feel like you understand it completely. The next day you can barely remember it. What learning principle were you not applying?', options: ['You need a more capable AI model', 'Spaced repetition and active recall: information is retained through repeated retrieval at increasing intervals. Feeling like you understand during the session is not the same as long-term retention — review the next day, then in 3 days, then in a week', 'The topic was too advanced for you', 'You were learning at the wrong time of day'], correct: 1, explanation: 'The forgetting curve is steep — without deliberate review, most information is forgotten within 24 hours. Feeling of understanding during a learning session (recognition) is not the same as being able to recall it later (retrieval). Apply spaced repetition: after a session, test yourself immediately, then in 1 day, 3 days, 1 week, and 1 month. Each successful retrieval strengthens the memory. Claude can help by generating test questions you haven\'t seen before — this tests actual retrieval, not just recognition.' }
  ]
},

'19-6': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — AI as Thinking Partner', content: 'Experience using Claude as a genuine thinking partner, not just an answer machine.\n\n**Step 1 — Choose a complex personal or professional challenge** you\'re working through.\n\n**Step 2 — Ask Claude to be a thinking partner, not an advisor:**\n```\nI want to think through [your challenge] out loud. Act as a thinking partner: help me explore the problem rather than immediately giving me solutions.\n\nAsk me questions that:\n- Help me clarify what I actually want\n- Surface assumptions I\'m making\n- Explore angles I haven\'t considered\n- Challenge my reasoning without dismissing it\n\nStart by asking me: what makes this situation feel difficult?\n```\n\n**Step 3 — Engage genuinely** — answer Claude\'s questions honestly.\n\n**Step 4 — After 10 exchanges**, ask: "Based on our conversation, what have I clarified? What am I still avoiding?"' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Regular Journaling Practice', content: 'Establish an AI-assisted journaling practice.\n\n**Step 1 — Ask Claude** to create a journaling system for you:\n```\nDesign a journaling practice that:\n- Takes 10-15 minutes daily\n- Uses AI for reflection (not just writing prompts, but actual back-and-forth)\n- Tracks: emotional state, progress toward goals, gratitude, one learning from today\n- Includes a weekly synthesis\n\nCreate the prompt structure for the daily journal and the weekly review.\n```\n\n**Step 2 — Do the daily journal** with Claude\'s prompts for 5 consecutive days.\n\n**Step 3 — After 5 days**, run the weekly synthesis: ask Claude to analyse your journal entries and identify: patterns, progress, concerns, and one question to sit with this week.\n\n**Step 4 — Evaluate:** Is AI-assisted journaling more valuable than journaling alone? What does the back-and-forth add?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Decision Journaling', content: 'Use AI to journal about decisions and track outcomes.\n\n**Step 1 — Identify a significant decision** you\'re in the process of making.\n\n**Step 2 — Ask Claude to help you journal through the decision:**\n```\nGuide me through decision journaling for this choice: [describe it]\n\nStructure:\n1. What is the exact decision? (Force me to be precise)\n2. What are my real options? (Not just the obvious ones)\n3. What does each option give me vs cost me?\n4. What am I most afraid of? (In making each choice)\n5. If a trusted mentor were watching this decision, what would they say?\n6. In 10 years, which choice would I regret not making?\n7. My current inclination: [what is it?] and the doubts I still have.\n```\n\n**Step 3 — Return to this journal entry** after making the decision.\n\n**Step 4 — In 3 months**, revisit the entry and evaluate: was my reasoning sound? What did I miss?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Insight Mining from Past Conversations', content: 'Extract insights from your history of AI conversations.\n\n**Step 1 — Identify a challenging period** in your life or work from the last year.\n\n**Step 2 — Write a narrative** of that period (10-15 minutes of stream-of-consciousness writing about what happened).\n\n**Step 3 — Ask Claude to help mine insights:**\n```\nAnalyse this narrative from a difficult period in my life/work:\n[paste your writing]\n\nHelp me extract:\n1. What strengths did I demonstrate that I should remember?\n2. What patterns of thinking or behaviour created difficulty?\n3. What did I learn about myself?\n4. What would I advise to my past self in that situation?\n5. How is this experience relevant to challenges I\'m facing now?\n```\n\n**Step 4 — Evaluate the insights.** Do they ring true? Are there patterns you\'re still repeating?' },

    { type: 'quiz', question: 'You use AI for daily journaling and find you\'re increasingly relying on Claude\'s reflections rather than developing your own. Is this a problem?', options: ['No — Claude\'s reflections are good quality', 'Yes — the goal of journaling is to develop your own self-understanding. Use AI to prompt reflection and challenge thinking, but ensure you\'re forming your own interpretations and conclusions', 'No — AI reflections are more objective than self-reflection', 'Only if you share the journal with others'], correct: 1, explanation: 'AI-assisted journaling works best when AI amplifies your self-reflection rather than replaces it. If you\'re accepting Claude\'s interpretations without forming your own, you\'re building a model of yourself as Claude sees you, not as you actually are. Healthy pattern: Claude asks questions → you reflect and answer → Claude challenges or extends → you refine. Unhealthy pattern: Claude interprets → you accept → you use Claude\'s interpretation as your self-understanding.' },

    { type: 'quiz', question: 'You tell Claude about a difficult situation at work and it responds empathetically and suggests several coping strategies. What important limitation should you keep in mind?', options: ['Claude\'s strategies are always evidence-based', 'Claude cannot verify your account, knows only what you tell it, and cannot observe context that might change the picture. For significant emotional or interpersonal challenges, professional support (therapist, counselor, mentor) provides something AI cannot', 'Claude\'s empathy is genuine', 'Coping strategies from AI are as effective as from human therapists'], correct: 1, explanation: 'AI emotional support has real limitations: (1) Claude only has your account of a situation — a therapist or coach can observe patterns across many sessions and challenge your narrative when appropriate; (2) Claude doesn\'t have clinical training in recognising when professional intervention is needed; (3) the relationship quality of human therapeutic support is meaningfully different from AI interaction. Use AI for everyday reflection and thinking-through; for significant mental health challenges, professional human support is essential.' }
  ]
},

'19-7': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Voice AI Capabilities Tour', content: 'Explore the capabilities of current voice AI tools.\n\n**Step 1 — Ask Claude (text):** "What are the leading voice AI systems currently? What can each do beyond basic voice-to-text? What makes Advanced Voice Mode in Claude or similar systems different from older voice assistants?"\n\n**Step 2 — Try voice interaction** with Claude (if available via the app) or another voice AI you have access to.\n\n**Step 3 — Test these scenarios:**\n- Complex multi-part question\n- Follow-up question that references your previous statement\n- Asking it to perform a task (set a reminder, draft a message)\n- Ambiguous request to see how it handles clarification\n\n**Step 4 — Compare to text interaction:** Where does voice AI add convenience? Where does text work better?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Voice AI for Hands-Free Tasks', content: 'Find real use cases where voice AI saves significant time.\n\n**Step 1 — Identify situations** where you\'re hands-busy or eyes-busy:\n- Commuting or driving\n- Cooking\n- Exercise\n- Manual tasks\n\n**Step 2 — Design voice AI workflows** for each:\n- Commuting: dictate meeting notes, hear news summaries, language learning\n- Cooking: recipe assistance without touching your phone\n- Exercise: motivation, logging workouts, podcast-style explanations of topics\n\n**Step 3 — Test one workflow** in the actual hands-busy situation.\n\n**Step 4 — Evaluate:** Was voice AI genuinely better than waiting until you\'re free? What friction remained (ambient noise, accent recognition, imprecise voice commands)?' },

    { type: 'workshop', tag: 'BROWSER', title: 'Workshop C — Voice Input for Text Output', content: 'Use voice input to speed up your text-based AI workflow.\n\n**Step 1 — Set up voice dictation** on your device:\n- Windows: Windows + H\n- Mac: Fn + Fn or System Preferences → Keyboard → Dictation\n\n**Step 2 — Dictate prompts instead of typing** for your next 5 Claude interactions.\n\n**Step 3 — Compare typing vs dictation** for:\n- Speed (words per minute)\n- Accuracy\n- Comfort with complex technical prompts\n- Fatigue over time\n\n**Step 4 — Identify prompt types** where dictation is faster vs types where typing is better.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Voice AI Limitations and Mitigation', content: 'Map voice AI limitations and build mitigation strategies.\n\n**Step 1 — Ask Claude:** "What are the main limitations of current voice AI: accuracy, context, privacy, latency, complex instructions? For each, what are the workarounds or acceptance criteria?"\n\n**Step 2 — Test each limitation** with your specific accent, environment, and typical use cases.\n\n**Step 3 — Build mitigation strategies:**\n- Accuracy issues: speak more slowly, use trigger phrases, verify complex outputs visually\n- Privacy: identify what you will and won\'t say to voice AI\n- Complex instructions: break into shorter commands\n\n**Step 4 — Define your voice AI usage policy:** What tasks will you routinely use voice AI for? What will you always do via text?' },

    { type: 'quiz', question: 'You dictate a voice message to an AI assistant and it mishears "delete" as "delay." The resulting action was wrong. What safeguard prevents this?', options: ['Use a higher quality microphone', 'Confirm before executing irreversible actions: any voice command that would modify, delete, or take irreversible action should be read back for confirmation before execution', 'Speak more slowly and clearly', 'Use text for important commands'], correct: 1, explanation: 'Voice recognition errors are inevitable, especially for similar-sounding words. For irreversible or significant actions: the system should always read back what it heard and what action it will take before executing. "You said \'delete all messages from John\' — shall I proceed?" This adds one confirmation step but prevents misheard commands from causing irreversible damage. Always use confirmation for: deletions, sends, purchases, and any action you can\'t easily undo.' },

    { type: 'quiz', question: 'Voice AI in a smart speaker records your conversations to improve accuracy. What should you consider?', options: ['Nothing — the recordings are encrypted', 'Privacy: what data is recorded, how long is it retained, who can access it, can it be used for training? Review the device\'s privacy policy and consider whether to use voice AI for sensitive conversations', 'Only a concern in public spaces', 'Only a concern if you discuss financial information'], correct: 1, explanation: 'Voice AI devices that record for accuracy improvement may store audio clips that include: conversations you intended to be private, sensitive personal information, and data you didn\'t intend to share. Actions: (1) read the privacy policy to understand what\'s recorded and retained; (2) regularly review and delete voice history in the app settings; (3) decide which rooms/situations warrant a physical mute; (4) don\'t discuss passwords, medical information, or private conversations near always-on voice devices.' }
  ]
},

'19-8': {
  addMinutes: 35,
  sections: [
    { type: 'workshop', tag: 'BROWSER', title: 'Workshop A — Second Brain Concept and Design', content: 'Design your personal second brain system.\n\n**Step 1 — Ask Claude:** "Explain the \'second brain\' concept for personal knowledge management. What are the leading methodologies (PARA, Zettelkasten, etc.)? What problems does a second brain solve?"\n\n**Step 2 — Audit your current personal organisation system:**\n- Where do your notes live? (multiple apps, messy, or non-existent)\n- How do you find information you know you\'ve captured?\n- How often does valuable information get lost?\n\n**Step 3 — Ask Claude to recommend a system** for your situation:\n"Based on these facts about how I work [describe your work style, tools you already use, types of information you manage], what personal knowledge management approach would work best for me?"\n\n**Step 4 — Choose your approach** and commit to trying it for 30 days.' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop B — Set Up Your Second Brain', content: 'Set up your personal knowledge management system.\n\n**Step 1 — Choose your primary tool** based on your workshop A research: Obsidian, Notion, Roam Research, or simple markdown files.\n\n**Step 2 — Ask Claude Code** to help set up the structure:\n```\nHelp me set up a personal knowledge management system in [Obsidian/markdown files].\n\nCreate:\n1. Folder structure based on PARA (Projects, Areas, Resources, Archives)\n2. Template files for: meeting notes, book notes, project notes, daily journal\n3. A README explaining how to use the system\n4. An index page that links to all active projects\n```\n\n**Step 3 — Migrate your 10 most important current notes** into the new system.\n\n**Step 4 — Set up the AI integration:** How will you use Claude to query and synthesise your second brain?' },

    { type: 'workshop', tag: 'TERMINAL', title: 'Workshop C — AI-Powered Note Search and Synthesis', content: 'Use AI to make your second brain queryable.\n\n**Step 1 — Build a simple query tool** for your markdown notes:\n```bash\n# Using the RAG system from Lesson 18-4, or a simpler approach:\n# Ask Claude Code to build a script that:\n# 1. Reads all markdown files in your notes folder\n# 2. Takes a query as input\n# 3. Uses grep + Claude to find and synthesise relevant notes\n# 4. Returns: relevant notes with quotes + a synthesis\n```\n\n**Step 2 — Test with 5 questions** that your notes should answer.\n\n**Step 3 — Evaluate retrieval quality.** Are the right notes surfacing?\n\n**Step 4 — Compare to manual search:** How much faster is AI-assisted search vs scrolling through folders?' },

    { type: 'workshop', tag: 'BUILD', title: 'Workshop D — Maintenance System and Habits', content: 'Build sustainable habits for maintaining your second brain.\n\n**Step 1 — Design a capture habit:** How will information get into your second brain consistently?\n- Quick capture (mobile note, email-to-notes, etc.)\n- Processing time (when do rough captures get organised?)\n\n**Step 2 — Design a review habit:**\n- Daily: 5-minute review of new captures\n- Weekly: process captures, link notes, review projects\n- Monthly: archive completed projects, identify pattern in captures\n\n**Step 3 — Ask Claude to create a weekly review prompt:**\n"Design a 20-minute weekly review prompt for a second brain system. The review should: process new captures, update active projects, identify connections between notes, and set intentions for next week."\n\n**Step 4 — Run the first weekly review** using the prompt. What needs adjusting?' },

    { type: 'quiz', question: 'After 3 months of using a second brain, you have 500 notes but can\'t find anything quickly. What is the most likely problem?', options: ['You have too many notes — start deleting', 'The system lacks structure or your tagging/linking is inconsistent — review your organisation system, add a consistent tagging convention, and create index pages for key topics', 'You need a more powerful search tool', 'Notes are most useful when you have fewer, better-quality ones'], correct: 1, explanation: '500 unfindable notes indicates an organisational failure, not a volume problem. Common causes: (1) captures without organisation (the "inbox" filled up and was never processed); (2) inconsistent naming or tagging (same concept stored under different labels); (3) no index pages (no way to navigate to related notes); (4) flat structure (everything in one folder). Fix: a one-time "notes review" to organise existing notes, then enforce a weekly processing habit where new captures get organised before the pile grows again.' },

    { type: 'quiz', question: 'You invest 10 hours setting up an elaborate second brain system. Six weeks later you\'ve stopped using it. What went wrong?', options: ['You chose the wrong tool', 'The system was too complex to maintain consistently — the best second brain is one you actually use, which means it must be simple enough to not feel like work', 'You needed more storage space', 'You should have used a different methodology'], correct: 1, explanation: 'Second brain abandonment is extremely common. The key failure: building a system for an idealised future self who has unlimited time and discipline, not for your actual self who has limited energy. Warning signs of an unsustainable system: it requires more than 15 minutes per day to maintain, there are complex rules that feel bureaucratic, and you procrastinate on capturing because "it\'s not worth setting up properly." Fix: start with the simplest possible system (one folder, one tag, one template), prove it works for a month, then add complexity only where there\'s a specific pain point.' }
  ]
}

};

function enhance(id, filePath) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const lesson = JSON.parse(raw);
  const enh = enhancements[id];
  if (!enh) { console.log('SKIP '+id); return; }
  let successIdx = -1;
  for (let i = lesson.sections.length - 1; i >= 0; i--) {
    if (lesson.sections[i].type === 'callout' && lesson.sections[i].variant === 'success') {
      successIdx = i; break;
    }
  }
  const insertAt = successIdx >= 0 ? successIdx : lesson.sections.length;
  lesson.sections.splice(insertAt, 0, ...enh.sections);
  lesson.estimatedMinutes += enh.addMinutes;
  fs.writeFileSync(filePath, JSON.stringify(lesson, null, 2));
  const ws = lesson.sections.filter(s=>s.type==='workshop').length;
  const qz = lesson.sections.filter(s=>s.type==='quiz').length;
  console.log('OK '+id+' | ws:'+ws+' qz:'+qz+' mins:'+lesson.estimatedMinutes);
}

